document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll("[data-toggle-password]").forEach(function(e){let o=document.getElementById(e.dataset.togglePassword);if(!o)return;let s=e.querySelector('[data-icon="show"]'),d=e.querySelector('[data-icon="hide"]');e.addEventListener("click",function(){let t=o.type==="password";o.type=t?"text":"password",s&&s.classList.toggle("hidden",t),d&&d.classList.toggle("hidden",!t),e.setAttribute("aria-pressed",t?"true":"false")})})});
